const tariff = 1444.70;
let st = global.get('evChargerState');
const now = Date.now();

function pad(n){ return String(n).padStart(2, '0'); }
function ts(d = new Date()){ return `${d.getFullYear()}-${pad(d.getMonth()+1)}-${pad(d.getDate())} ${pad(d.getHours())}:${pad(d.getMinutes())}:${pad(d.getSeconds())}`; }
function rp(v){ return 'Rp ' + Math.round(v).toLocaleString('id-ID'); }

if (!st) {
    st = {
        status: 'charging',
        level: 18,
        cycleNo: 1,
        cycleStartedAt: now,
        last: now,
        energyCycle: 0,
        totalEnergy: 0,
        totalCost: 0,
        powerKw: 0,
        history: []
    };
}

let dt = Math.min(Math.max((now - st.last) / 1000, 0), 5);
st.last = now;
let plnV = 217 + Math.random() * 14;
let chargerV = 380 + Math.random() * 34;

if (st.status === 'charging') {
    let p;
    if (st.level < 80) p = 6.0 + Math.random() * 1.4;
    else if (st.level < 95) p = 3.0 + Math.random() * 2.5;
    else p = 0.8 + Math.random() * 1.4;

    st.powerKw = Math.max(0, p + (Math.random() - 0.5) * 0.4);
    const addKwh = st.powerKw * dt / 3600;
    st.energyCycle += addKwh;
    st.totalEnergy += addKwh;
    st.totalCost = st.totalEnergy * tariff;
    st.level += st.powerKw * dt * 0.035;

    if (st.level >= 100) {
        st.level = 100;
        const end = new Date();
        const start = new Date(st.cycleStartedAt);
        st.history.unshift({
            cycle_id: `CHG-${end.getFullYear()}${pad(end.getMonth()+1)}${pad(end.getDate())}-${String(st.cycleNo).padStart(3, '0')}`,
            started_at: ts(start),
            ended_at: ts(end),
            duration_min: Math.max(1, Math.floor((now - st.cycleStartedAt) / 60000)),
            energy_kwh: Number(st.energyCycle.toFixed(3)),
            cost_rp: Math.round(st.energyCycle * tariff),
            status: 'completed'
        });
        st.history = st.history.slice(0, 25);
        st.status = 'idle';
        st.powerKw = 0;
        st.cycleNo += 1;
        st.idleAt = now;
    }
} else if (st.status === 'idle') {
    st.powerKw = 0;
    if (now - (st.idleAt || now) > 12000) {
        st.status = 'charging';
        st.level = 8 + Math.random() * 20;
        st.energyCycle = 0;
        st.cycleStartedAt = now;
    }
} else if (st.status === 'paused') {
    st.powerKw = 0;
}

global.set('evChargerState', st);
msg.payload = {
    source: 'node-red-dummy',
    timestamp: ts(),
    status: st.status,
    status_label: st.status === 'charging' ? 'Sedang Charging' : (st.status === 'paused' ? 'Pause' : 'Standby'),
    level_percent: Number(st.level.toFixed(1)),
    charger_power_kw: Number(st.powerKw.toFixed(3)),
    charger_power_w: Math.round(st.powerKw * 1000),
    charger_voltage_v: Number(chargerV.toFixed(1)),
    pln_voltage_v: Number(plnV.toFixed(1)),
    cycle_energy_kwh: Number(st.energyCycle.toFixed(4)),
    cycle_cost_rp: Math.round(st.energyCycle * tariff),
    cycle_cost_text: rp(st.energyCycle * tariff),
    tariff_rp_per_kwh: tariff,
    total_energy_kwh: Number(st.totalEnergy.toFixed(4)),
    total_cost_rp: Math.round(st.totalCost),
    total_cost_text: rp(st.totalCost),
    cycle_started_at: ts(new Date(st.cycleStartedAt))
};
return msg;

let st = global.get('evChargerState') || {history: [], cycleNo: 1, status: 'idle', energyCycle: 0, cycleStartedAt: Date.now()};
function pad(n){ return String(n).padStart(2, '0'); }
function ts(d = new Date()){ return `${d.getFullYear()}-${pad(d.getMonth()+1)}-${pad(d.getDate())} ${pad(d.getHours())}:${pad(d.getMinutes())}:${pad(d.getSeconds())}`; }
const active = {
    cycle_id: `CHG-ACTIVE-${String(st.cycleNo || 1).padStart(3, '0')}`,
    started_at: ts(new Date(st.cycleStartedAt || Date.now())),
    ended_at: '-',
    duration_min: Math.floor((Date.now() - (st.cycleStartedAt || Date.now())) / 60000),
    energy_kwh: Number((st.energyCycle || 0).toFixed(3)),
    cost_rp: Math.round((st.energyCycle || 0) * 1444.70),
    status: st.status || 'idle'
};
msg.payload = { source: 'node-red-dummy', items: [active, ...(st.history || [])] };
return msg;

const tariff = 1444.70;
let st = global.get('evChargerState') || {history: [], totalEnergy: 0, totalCost: 0, energyCycle: 0};
function rp(v){ return 'Rp ' + Math.round(v).toLocaleString('id-ID'); }
msg.payload = {
    source: 'node-red-dummy',
    total_cost_rp: Math.round(st.totalCost || 0),
    total_cost_text: rp(st.totalCost || 0),
    total_energy_kwh: Number((st.totalEnergy || 0).toFixed(4)),
    tariff_rp_per_kwh: tariff,
    total_cycles: (st.history || []).length,
    active_cycle_energy_kwh: Number((st.energyCycle || 0).toFixed(4)),
    active_cycle_cost_rp: Math.round((st.energyCycle || 0) * tariff),
    active_cycle_cost_text: rp((st.energyCycle || 0) * tariff)
};
return msg;

let st = global.get('evChargerState');
const action = msg.payload && msg.payload.action;
if (!st || action === 'reset') {
    st = null;
    global.set('evChargerState', st);
    msg.payload = { ok: true, action: 'reset', status: 'reset' };
    return msg;
}
if (action === 'start') st.status = 'charging';
if (action === 'pause') st.status = 'paused';
global.set('evChargerState', st);
msg.payload = { ok: true, action, status: st.status };
return msg;
